TEMPLATES = {
    "workflow/studio_assets": """<link rel="stylesheet" href="/static/audit-studio.css"><script src="/static/vendor/ag-studio.min.js" defer></script><script src="/static/studio-grid.js" defer></script><script src="/static/audit-studio.js" defer></script>""",
    "workflow/common": """<style>""" + CSS + """</style>{% if notice %}<div class="notice success workflow-alert" role="status">{{ notice }}</div>{% endif %}{% if error %}<div class="notice error workflow-alert" role="alert">{{ error }}</div>{% endif %}""",
    "workflow/spec": """<fieldset class="workflow-spec"><legend>{{ 'Additional deliverable (optional)' if optional else 'Deliverable ' ~ (index + 1) }}</legend>
<input type="hidden" name="deliverable_key" value="{{ spec.key|default('') }}">
<div class="field"><label for="deliverable-name-{{ index }}">Deliverable name</label><input id="deliverable-name-{{ index }}" name="deliverable_name" value="{{ spec.name|default('') }}" maxlength="120" placeholder="Name the output you want"{% if not optional %} required{% endif %}></div>
<div class="field"><label for="deliverable-description-{{ index }}">What should the output contain?</label><textarea id="deliverable-description-{{ index }}" name="deliverable_description" rows="3" maxlength="2000" placeholder="Describe the content and format you expect.">{{ spec.description|default('') }}</textarea></div>
<div class="field"><label for="deliverable-criteria-{{ index }}">Completion criteria</label><textarea id="deliverable-criteria-{{ index }}" name="deliverable_criteria" rows="4" maxlength="4000" aria-describedby="criteria-hint-{{ index }}" placeholder="One clear criterion per line"{% if not optional %} required{% endif %}>{{ spec.criteria|default([])|join('\n') }}</textarea><p id="criteria-hint-{{ index }}" class="field-hint">Every criterion must pass before this deliverable is submitted for your review.</p></div>
{% if cfg.scenario|default("generic") == "general" %}<p class="field-hint">Model writing is checked against these criteria and submitted for your review. This workflow does not make purchases or publish externally.</p>{% elif cfg.scenario|default("generic") == "browser_purchase" %}<p class="field-hint">This proposal is delivered for your review before any purchase. Checkout and ad publication remain blocked.</p>{% elif cfg.scenario|default("generic") != "pocketplan_ads" %}<div class="workflow-check"><input id="purchase-required-{{ index }}" type="checkbox" name="purchase_required_{{ index }}"{% if spec.purchase_required|default(false) %} checked{% endif %}><label for="purchase-required-{{ index }}">This work needs a purchased resource<span class="workflow-stat-detail">The agent will request your approval before checkout. A delivered resource can be reused.</span></label></div>{% else %}<p class="field-hint">Campaign planning and creative are delivered before purchase approval. Advertising requires a separate, exact campaign approval.</p>{% endif %}
{% if cfg.execution_mode|default("local") != "render" and cfg.scenario|default("generic") not in ("browser_purchase", "general") %}<details class="workflow-demo"><summary>Demo scenario</summary><div class="field"><label for="validation-scenario-{{ index }}">Completion check</label><select id="validation-scenario-{{ index }}" name="validation_scenario_{{ index }}"><option value="pass"{% if spec.validation_scenario|default('pass') == 'pass' %} selected{% endif %}>Pass configured checks</option><option value="needs_work_once"{% if spec.validation_scenario|default('pass') == 'needs_work_once' %} selected{% endif %}>Need a correction before submission</option></select><p class="field-hint">{% if cfg.inference_mode|default('fixture') == 'openai' %}Campaign plans and performance reports use GPT-6 Sol. This scenario setting applies only to fixture-based outputs.{% else %}Scenario data demonstrates the review states; no real agent or model runs.{% endif %}</p></div></details>{% endif %}</fieldset>""",
    "workflow/config": """{% extends 'base' %}{% block eyebrow %}Set up · Schedule · Review{% endblock %}{% block subtitle %}Define the work once. Your schedule creates jobs; Audit brings decisions and results back to you.{% endblock %}
{% block header_actions %}<a class="button secondary" href="/audit?instance_id={{ cfg.instance_id }}&amp;view=deliverables">View deliverables</a>{% endblock %}
{% block body %}{% set request_instance_id = cfg.instance_id %}{% include "requests/attention" %}{% include 'workflow/common' %}<nav class="workflow-tabs" aria-label="Agent sections"><a href="/instances/{{ cfg.instance_id }}/workflow" aria-current="page">Workflow</a><a href="/instances/{{ cfg.instance_id }}#overview">AICL controls</a><a href="/instances/{{ cfg.instance_id }}#funding">Funding</a><a href="/audit?instance_id={{ cfg.instance_id }}">Audit</a></nav>
<div class="workflow-layout"><section class="card"><div class="card-header"><div><p class="kicker">1 · DEFINE THE OUTCOME</p><h2>Goals &amp; deliverables</h2></div><span class="status-badge {{ 'active' if cfg.saved else 'draft' }}">{{ 'Saved · v' ~ cfg.version if cfg.saved else 'Needs configuration' }}</span></div><div class="card-body"><p class="muted">Describe the work your agent should produce and how it will know the result is complete.</p>
{% if not cfg.saved %}<section class="workflow-condition"><strong>Choose a starting workflow</strong><p>Choose General agent below for custom model-generated work. You can also start with a browser purchase proposal or the app marketing example.</p><form method="post" action="/instances/{{ cfg.instance_id }}/workflow/example"><input type="hidden" name="csrf_token" value="{{ csrf }}"><input type="hidden" name="expected_version" value="{{ cfg.version }}"><div class="button-row"><button type="submit" class="primary" name="example" value="browser_purchase">Use browser purchase workflow</button><button type="submit" class="secondary" name="example" value="pocketplan_ads">Use app marketing example</button></div></form><p class="field-hint">Saves goals, criteria and a daily schedule. Review them before enabling work; funding and purchases still need your approval.</p></section>{% elif cfg.scenario|default("generic") == "general" %}<p class="workflow-condition"><strong>General agent</strong><br>Your instructions → approved tools → model-generated deliverables → your review. Results appear in Habitat.</p>{% if cfg.inference_mode|default("fixture") != "openai" %}<p class="notice info">This workflow requires real model inference. The model is not enabled in this environment, so scheduled generation is unavailable.</p>{% endif %}{% elif cfg.scenario|default("generic") == "browser_purchase" %}<p class="workflow-condition"><strong>Browser purchase workflow · Stops before checkout</strong><br>Scheduled work → sign-in request if needed → website evidence → purchase proposal for approval. No ads are published or payments made.</p>{% elif cfg.scenario|default("generic") == "pocketplan_ads" %}<p class="workflow-condition"><strong>PocketPlan · App marketing</strong><br>Campaign plan → ad creative → owner-approved advertising → performance reports.</p>{% endif %}
<form method="post" action="/instances/{{ cfg.instance_id }}/workflow/config" id="workflow-config-form">{% if not cfg.saved and cfg.scenario|default('generic') == 'generic' %}<div class="field"><label for="workflow-type">Workflow type</label><select id="workflow-type" name="scenario"><option value="generic" selected>Local demonstration</option><option value="general">General agent</option></select><p class="field-hint">General agents use real model generation. Save once to choose tools and review their controls.</p></div>{% else %}<input type="hidden" name="scenario" value="{{ cfg.scenario|default('generic') }}">{% endif %}<input type="hidden" name="csrf_token" value="{{ csrf }}"><input type="hidden" name="expected_version" value="{{ cfg.version }}"><div class="field"><label for="workflow-goal">Agent goal</label><textarea id="workflow-goal" name="goal" required maxlength="2000" rows="3">{{ cfg.goal }}</textarea></div><div class="field"><label for="workflow-inputs">Context and inputs</label><textarea id="workflow-inputs" name="inputs" maxlength="4000" rows="3" placeholder="Who is this for? What background should the agent use?">{{ cfg.inputs }}</textarea></div>
{% if cfg.scenario|default("generic") == "general" %}<fieldset class="workflow-spec"><legend>Tools (optional)</legend><p class="field-hint">Choose the tools your agent may use. With public web search, the agent chooses queries and sources, up to one search invocation per deliverable. Leave all unchecked to use supplied context only.</p>{% for tool in tool_catalog %}<div class="workflow-check"><input id="tool-{{ tool.id }}" type="checkbox" name="tools" value="{{ tool.id }}"{% if tool.id in cfg.tools|default([]) %} checked{% endif %}><label for="tool-{{ tool.id }}">{{ tool.title }}<span class="workflow-stat-detail">{{ tool.description }}</span></label></div>{% endfor %}<p class="field-hint">Saving your selection authorizes the agent to use these tools during eligible runs. It does not authorize messages, publishing, payments or shell actions.</p></fieldset>{% endif %}
{% if cfg.scenario|default("generic") == "browser_purchase" %}{% set task = cfg.browser_task|default({}) %}<fieldset class="workflow-spec"><legend>Website &amp; purchase scope</legend>
<div class="field"><label for="browser-service-url">Website to review</label><input id="browser-service-url" name="browser_service_url" type="url" value="{{ task.service_url|default('') }}" required maxlength="2000" placeholder="https://ads.snapchat.com/"><p class="field-hint">Use the service's public HTTPS address without query parameters or login tokens. If access needs a login, the agent pauses and asks you in Requests.</p></div>
<div class="field"><label for="browser-objective">What purchase should the agent prepare?</label><textarea id="browser-objective" name="browser_objective" rows="3" required maxlength="2000">{{ task.objective|default('') }}</textarea></div>
<div class="field"><label for="browser-max-amount">Maximum proposed purchase (USD)</label><input id="browser-max-amount" name="browser_max_amount" type="number" min="0.01" max="10000" step="0.01" value="{{ money(task.max_amount_minor|default(2500)) }}" required><p class="field-hint">A cap for the proposal, not permission to spend. AICL controls and your exact purchase decision still apply.</p></div></fieldset>{% endif %}
{% for spec in cfg.deliverables %}<details{% if loop.first %} open{% endif %}><summary>{{ spec.name }} · {{ spec.criteria|length }} completion criteria</summary>{% with index=loop.index0, optional=false %}{% include 'workflow/spec' %}{% endwith %}</details>{% else %}{% with spec={}, index=0, optional=false %}{% include 'workflow/spec' %}{% endwith %}{% endfor %}
{% if cfg.deliverables and cfg.deliverables|length < 6 and cfg.scenario|default("generic") not in ("pocketplan_ads", "browser_purchase") %}<details><summary>Add another deliverable</summary>{% with spec={}, index=cfg.deliverables|length, optional=true %}{% include 'workflow/spec' %}{% endwith %}</details>{% endif %}
<div class="workflow-field-row"><div class="field"><label for="workflow-cadence">Schedule</label><select id="workflow-cadence" name="cadence"><option value="daily"{% if cfg.cadence == 'daily' %} selected{% endif %}>Every day at 9:00 AM</option><option value="hourly"{% if cfg.cadence == 'hourly' %} selected{% endif %}>Every hour</option></select></div><div class="field"><label for="workflow-timezone">Timezone</label><input id="workflow-timezone" name="timezone" value="{{ cfg.timezone }}" required maxlength="64" aria-describedby="timezone-hint"><p id="timezone-hint" class="field-hint">Use an IANA timezone, e.g. America/New_York.</p></div></div>
<div class="form-actions"><button type="submit" class="primary">Save configuration</button><span class="field-hint">Applies to future jobs. Existing results keep their original criteria.</span></div></form></div></section>
<div class="workflow-stack"><section class="card"><div class="card-header"><div><p class="kicker">2 · SET THE BOUNDARIES</p><h2>Controls &amp; funding</h2></div></div><div class="card-body"><p><strong>Service credit: ${{ credit(agent.balance_micro_usd|default(0)) }}</strong></p><p class="muted">{% if cfg.scenario|default("generic") == "general" %}Model generation uses service credit and your inference limits. Review these controls before enabling work. Tool use stays limited to your approved tools and the per-deliverable search limit.{% else %}Inference uses service credit. Purchase allowance limits spending with sellers; each purchase still needs your approval.{% endif %}</p><div class="button-row"><a class="button secondary" href="/instances/{{ cfg.instance_id }}#overview">Review AICL controls</a><a class="button ghost" href="/instances/{{ cfg.instance_id }}#funding">Fund with PayPal</a></div></div></section>
<section class="card" id="schedule"><div class="card-header"><div><p class="kicker">3 · ENABLE SCHEDULED WORK</p><h2>{{ 'Schedule enabled' if cfg.enabled else 'Schedule paused' }}</h2></div><span class="status-badge {{ 'active' if cfg.enabled else 'paused' }}">{{ 'Enabled' if cfg.enabled else 'Paused' }}</span></div><div class="card-body"><p>Runs {{ 'every hour' if cfg.cadence == 'hourly' else 'every day at 9:00 AM' }} · {{ cfg.timezone }}</p><p class="workflow-next">{{ date_label(cfg.next_due, cfg.timezone) if cfg.next_due else 'No upcoming run' }}</p><p class="field-hint">{{ 'Next scheduled occurrence' if cfg.next_due else 'Save the configuration, review controls, then enable the schedule.' }}</p>{% if cfg.last_outcome %}<p class="workflow-condition"><strong>Last outcome:</strong> {{ label(cfg.last_outcome) }}</p>{% endif %}<form method="post" action="/instances/{{ cfg.instance_id }}/workflow/schedule"><input type="hidden" name="csrf_token" value="{{ csrf }}"><input type="hidden" name="expected_version" value="{{ cfg.version }}"><input type="hidden" name="expected_instance_version" value="{{ cfg.instance_version }}"><input type="hidden" name="enabled" value="{{ 'false' if cfg.enabled else 'true' }}"><button class="{{ 'secondary' if cfg.enabled else 'primary' }}" type="submit"{% if not cfg.saved %} disabled{% endif %}>{{ 'Pause schedule' if cfg.enabled else 'Enable schedule' }}</button></form><p class="field-hint">The agent works at scheduled times. Pausing preserves all previous requests and results.</p></div></section>
<section class="guide-card"><p class="kicker">REVIEW ON YOUR TERMS</p><h2>Audit is always available.</h2>{% if cfg.scenario|default("generic") == "general" %}<p>Read each output, inspect its tool use and costs, and request revisions. Questions from your agent appear in Requests.</p><a href="/audit?instance_id={{ cfg.instance_id }}&amp;view=deliverables">View job deliverables →</a><p><a href="/requests?instance_id={{ cfg.instance_id }}">Answer agent questions →</a></p>{% else %}<p>Review purchase requests from past jobs, inspect costs, and accept or request changes to completed work.</p><a href="/audit?instance_id={{ cfg.instance_id }}&amp;view=purchases">Review purchases{% if agent.pending_purchase_count|default(0) %} · {{ agent.pending_purchase_count }} pending{% endif %} →</a><p><a href="/audit?instance_id={{ cfg.instance_id }}&amp;view=deliverables">View job deliverables →</a></p>{% endif %}</section>
{% if cfg.execution_mode|default("local") != "render" %}<details class="workflow-demo"><summary>{{ "Local run controls" if cfg.scenario|default("generic") == "general" else "Demo controls" }}</summary><p>Advance to the next scheduled occurrence without waiting. The same occurrence cannot create duplicate jobs or charges.</p><form method="post" action="/instances/{{ cfg.instance_id }}/workflow/advance"><input type="hidden" name="csrf_token" value="{{ csrf }}"><input type="hidden" name="expected_due" value="{{ cfg.next_due or '' }}"><button class="secondary" type="submit"{% if not cfg.enabled or not cfg.next_due %} disabled{% endif %}>Advance to next scheduled run</button></form></details>{% else %}<p class="workflow-hint">Render checks for due work automatically. Jobs run even while this page is closed, subject to your current AICL controls.</p>{% endif %}</div></div>
{% if overview.runs %}<section class="card" style="margin-top:24px"><div class="card-header"><h2>Recent jobs</h2><a href="/audit?instance_id={{ cfg.instance_id }}&amp;view=actions">View Audit</a></div><div class="card-body table-wrap"><table class="data-table"><thead><tr><th>Deliverable</th><th>Scheduled for</th><th>State</th><th>Inference</th></tr></thead><tbody>{% for run in overview.runs[:8] %}<tr><td><a href="{{ record_url('/audit/jobs/' ~ run.id) }}">{{ run.deliverable_name }}</a></td><td>{{ date_label(run.scheduled_for, cfg.timezone) }}</td><td>{{ label(run.state) }}{% if run.blocked_reason %}<p class="field-hint">{{ label(run.blocked_reason) }}</p>{% endif %}</td><td>${{ credit(run.inference_cost_micro_usd|default(0)) }}</td></tr>{% endfor %}</tbody></table></div></section>{% endif %}
<p class="workflow-footer">{% if cfg.scenario|default("generic") == "general" %}General agents require real model generation. Results appear in Habitat for owner review. Approved web search lets the agent choose public queries and sources; without tools, output uses supplied context. {% if cfg.execution_mode|default("local") != "render" %}Local mode requires you to advance each scheduled occurrence; automatic background scheduling is not active.{% endif %}{% elif cfg.scenario|default("generic") == "browser_purchase" %}Browser work collects evidence for a proposal. Website support and account access are checked during the run; this workflow stops before checkout and ad publication.{% elif cfg.inference_mode|default('fixture') == 'openai' %}Campaign plans and performance reports use GPT-6 Sol. Advertising delivery and metrics remain scenario data. {{ 'PayPal Sandbox payments use test funds.' if overview.payment_transport == 'paypal_sandbox' else 'Payments use local scenario data.' }}{% elif overview.payment_transport == 'paypal_sandbox' %}PayPal Sandbox payments use test funds. Scheduled work, validation and advertising remain simulated.{% else %}Demo environment · scheduled work, validation and payments use local scenario data.{% endif %}</p>{% endblock %}""",
    "workflow/audit": """{% extends 'base' %}{% set page_key='audit' %}{% block eyebrow %}{% endblock %}{% block subtitle %}Spending, purchase decisions and deliverables.{% endblock %}
{% block header_actions %}{% if instance_id %}<a class="button secondary small" href="/instances/{{ instance_id }}/workflow">Agent workflow</a>{% endif %}{% endblock %}
{% block body %}{% include 'workflow/common' %}<div class="audit-workspace">
{% include 'audit/navigation' %}
<form method="get" action="/audit" class="workflow-filter audit-filter"><input type="hidden" name="view" value="{{ view }}">{% for key, value in saved_statuses|default({})|items if key != "status_" ~ view %}<input type="hidden" name="{{ key }}" value="{{ value }}">{% endfor %}
<div class="field audit-agent"><label for="audit-agent">Agent</label><select id="audit-agent" name="instance_id"><option value="">All agents</option>{% for a in agents %}<option value="{{ a.id }}"{% if instance_id == a.id %} selected{% endif %}>{{ a.name }}</option>{% endfor %}</select></div>
{% if status_options %}<div class="field audit-status"><label for="audit-status">Status</label><select id="audit-status" name="status">{% for key, name in status_options %}<option value="{{ key }}"{% if status == key %} selected{% endif %}>{{ name }}</option>{% endfor %}</select></div>{% endif %}
<details class="audit-dates"{% if date_from or date_to %} open{% endif %}><summary>Date range{% if date_from or date_to %}<span class="workflow-inline-count">Set</span>{% endif %}</summary><div class="audit-date-fields"><div class="field"><label for="audit-date-from">Created from</label><input id="audit-date-from" type="date" name="date_from" value="{{ date_from }}"></div><div class="field"><label for="audit-date-to">Created through</label><input id="audit-date-to" type="date" name="date_to" value="{{ date_to }}"></div><p class="field-hint">Entry dates · America/New_York</p></div></details>
<div class="audit-filter-actions"><button class="secondary" type="submit">Apply filters</button>{% if filters_active %}<a href="{{ audit_url(view) }}">Clear filters</a>{% endif %}</div></form>
{% if view == 'costs' %}{% include 'workflow/costs' %}{% elif view == 'actions' %}{% include 'workflow/actions' %}{% elif view == 'purchases' %}{% include 'workflow/purchases' %}{% elif view == 'campaigns' %}{% include 'workflow/campaigns' %}{% else %}{% include 'workflow/deliverables' %}{% endif %}
<p class="workflow-footer">{% if d.has_runtime_runs|default(false) %}Saved agent runs, actions and outputs appear here with their recorded cost evidence. Open the source work to review provenance and coverage. Generated claims still need owner review.{% elif d.has_general_agents|default(false) %}General agent outputs use real model generation and appear here for owner review. Source coverage depends on the saved configuration; generated claims still need review. {% if d.inference_mode|default("fixture") != "openai" %}Model generation is unavailable in this environment.{% endif %}{% elif d.inference_mode|default('fixture') == 'openai' %}Campaign plans and performance reports use GPT-6 Sol. Advertising delivery and metrics remain scenario data. {{ 'PayPal Sandbox payments use test funds.' if d.payment_transport == 'paypal_sandbox' else 'Payments use local scenario data.' }}{% elif d.payment_transport == 'paypal_sandbox' %}PayPal Sandbox payments use test funds. Inference, scheduled work and advertising remain simulated.{% else %}Demo data · costs, scheduled work and payments are simulated locally.{% endif %} Service credit and merchant spending are separate.</p></div>{% endblock %}""",
    "workflow/job_costs": """{% if job.cost_summary is defined %}{% set summary = job.cost_summary %}
<section class="card audit-cost-section" id="cost-breakdown"><div class="card-header"><div><h2>Cost breakdown</h2><p class="muted">Full job history, linked to each source step. Date filters are retained for navigation. Funding and merchant payments remain separate.</p></div></div><div class="card-body">
<div class="audit-cost-summary"><span>Recorded usage <strong>${{ credit(summary.settled_micro_usd) }}</strong></span><span>Estimated <strong>${{ credit(summary.estimated_micro_usd) }}</strong></span><span>Reserved <strong>${{ credit(summary.held_micro_usd) }}</strong></span></div>
<div class="audit-resource-breakdown">{% for component in summary.components %}<article><span>{{ component.label }}</span><strong>{{ '$' ~ credit(component.amount_micro_usd) if component.amount_micro_usd is not none else 'Included in combined charge' if component.coverage == 'bundled' else 'No separate amount' }}</strong><small>{{ component.coverage_note }}</small></article>{% endfor %}</div>
<div id="job-cost-grid" class="audit-studio-table" data-kind="costs" data-source="job-cost-data" data-fallback="job-cost-fallback" data-license-key="{{ studio_license_key|default('') }}" aria-label="Job cost entries" hidden></div>
<div id="job-cost-fallback" class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Resource</th><th>Amount</th><th>Accounting</th><th>Coverage</th><th>Source</th></tr></thead><tbody>{% for row in job.cost_rows %}<tr><td>{{ date_label(row.created_at) }}</td><td>{{ row.component_label }}</td><td>${{ '%.6f'|format(row.amount_usd) }}</td><td>{{ label(row.charge_kind) }}</td><td>{{ row.coverage_note }}</td><td>{% if row.evidence_url %}<a href="{{ record_url(row.evidence_url) }}">View source</a>{% endif %}</td></tr>{% else %}<tr><td colspan="6">No cost entries recorded for this job. Unmetered access is not assumed free.</td></tr>{% endfor %}</tbody></table></div>
</div></section><script id="job-cost-data" type="application/json">{{ job.cost_rows|tojson }}</script>{% include 'workflow/studio_assets' %}{% endif %}
""",
    "workflow/costs": """<p class="audit-summary-note">Current balances stay current. Usage and estimates follow the selected period.</p>
{% set summary = d.cost_summary|default({}) %}
<div class="workflow-stats">
<div class="stat-card"><span class="stat-label">Recorded usage</span><strong class="stat-value">${{ credit(summary.settled_micro_usd|default(0)) }}</strong><span class="stat-note">Recorded model, tool and compute charges</span></div>
<div class="stat-card"><span class="stat-label">Estimated usage</span><strong class="stat-value">${{ credit(summary.estimated_micro_usd|default(0)) }}</strong><span class="stat-note">Estimates kept separate from charges</span></div>
<div class="stat-card"><span class="stat-label">Reserved in this period</span><strong class="stat-value">${{ credit(summary.held_micro_usd|default(0)) }}</strong><span class="stat-note">Unsettled amounts · excluded from usage</span></div>
<div class="stat-card"><span class="stat-label">Service credit remaining</span><strong class="stat-value">${{ credit(d.totals.service_balance_micro_usd) }}</strong><span class="stat-note">Current available funds</span></div>
</div>
<div class="audit-resource-breakdown" aria-label="Resource cost breakdown">
{% for component in summary.components|default([]) %}<article><span>{{ component.label }}</span><strong>{{ '$' ~ credit(component.amount_micro_usd) if component.amount_micro_usd is not none else 'Included in combined charge' if component.coverage == 'bundled' else 'No separate amount' }}</strong><small>{{ component.coverage_note }}</small></article>{% endfor %}
</div>
<p class="audit-summary-note">Model and tool fees stay combined when the original meter recorded one charge. Unmetered access is not assumed free. Funding, reservations and merchant payments are excluded from usage totals.</p>
<p class="audit-summary-note">Merchant payments: ${{ money(d.totals.purchase_spent_minor) }} · ${{ money(d.totals.purchase_held_minor) }} reserved · <a href="{{ audit_url('purchases', instance_id, date_from|default(''), date_to|default(''), saved_statuses|default({})) }}">Review purchases</a></p>
{% if d.campaigns or d.totals.ad_funding_minor|default(0) > 0 %}<div class="workflow-stats campaign-summary"><div class="stat-card"><span class="stat-label">Advertising prepaid</span><strong class="stat-value">${{ money(d.totals.ad_funding_minor) }}</strong><span class="stat-note">Included in merchant payments above</span></div><div class="stat-card"><span class="stat-label">Ad spend consumed</span><strong class="stat-value">${{ money(d.totals.ad_consumed_minor) }}</strong><span class="stat-note">Used from prepaid advertising funds</span></div><div class="stat-card"><span class="stat-label">Ad funds remaining</span><strong class="stat-value">${{ money(d.totals.ad_remaining_minor) }}</strong><span class="stat-note">Prepaid minus consumed · <a href="{{ audit_url('campaigns', instance_id, date_from|default(''), date_to|default(''), saved_statuses|default({})) }}">View campaigns</a></span></div></div><p class="audit-summary-note">Prepaid funding and consumed ad spend are two views of the same funds, not additional charges.</p>{% endif %}
<section class="card audit-cost-section"><div class="card-header"><div><h2>Cost by job</h2><p class="muted">Start with a job total, then open its source to inspect the work and charges. Setup and unallocated costs stay at agent level.</p></div></div><div class="card-body">
<div id="audit-job-cost-grid" class="audit-studio-table" data-kind="cost_jobs" data-source="audit-job-cost-data" data-fallback="audit-job-cost-fallback" data-license-key="{{ studio_license_key|default('') }}" aria-label="Cost by job table" hidden></div>
<div id="audit-job-cost-fallback" class="table-wrap"><table class="data-table"><thead><tr><th>Agent</th><th>Job / allocation</th><th>Recorded</th><th>Estimated</th><th>Reserved</th><th>Resources</th><th>Source</th></tr></thead><tbody>{% for row in d.cost_jobs|default([]) %}<tr><td>{{ row.agent_name }}</td><td>{{ row.job_name }}</td><td>${{ '%.6f'|format(row.settled_usd) }}</td><td>${{ '%.6f'|format(row.estimated_usd) }}</td><td>${{ '%.6f'|format(row.held_usd) }}</td><td>{{ row.components }}</td><td>{% if row.evidence_url %}<a href="{{ record_url(row.evidence_url) }}">View source</a>{% endif %}</td></tr>{% else %}<tr><td colspan="7">No costs recorded for the selected period.</td></tr>{% endfor %}</tbody></table></div>
</div></section>
<script id="audit-job-cost-data" type="application/json">{{ d.cost_jobs|default([])|tojson }}</script>
<section class="card audit-cost-section"><div class="card-header"><div><h2>Individual cost entries</h2><p class="muted">Each recorded charge, estimate, reservation and funding entry, linked to its evidence.</p></div></div><div class="card-body">
<div id="audit-cost-grid" class="audit-studio-table" data-kind="costs" data-source="audit-cost-data" data-fallback="audit-cost-fallback" data-license-key="{{ studio_license_key|default('') }}" aria-label="Cost and statistics table" hidden></div>
<div id="audit-cost-fallback" class="table-wrap"><table class="data-table"><caption class="field-hint">Funding is not an expense. Estimated and reserved amounts are separate from recorded usage.</caption><thead><tr><th>Date</th><th>Agent</th><th>Resource</th><th>Entry</th><th>Amount (USD)</th><th>Accounting</th><th>Status</th><th>Source</th></tr></thead><tbody>{% for row in d.cost_rows %}<tr><td>{{ date_label(row.created_at) }}</td><td>{{ row.agent_name }}</td><td>{{ row.component_label }}</td><td>{{ label(row.category) }}</td><td>{{ '%.6f'|format(row.amount_usd) }}</td><td>{{ label(row.charge_kind) }}</td><td>{{ label(row.status) }}</td><td>{% if row.evidence_url %}<a href="{{ record_url(row.evidence_url) }}">View source</a>{% endif %}</td></tr>{% else %}<tr><td colspan="8">No activity recorded in this period.</td></tr>{% endfor %}</tbody></table></div>
</div></section>
<script id="audit-cost-data" type="application/json">{{ d.cost_rows|tojson }}</script>{% include 'workflow/studio_assets' %}
""",
    "workflow/campaigns": """<div class="section-heading"><div><h2>Campaigns &amp; results</h2><p class="muted">Payment funds a campaign. Scheduled jobs record ad delivery and performance separately.</p></div></div><div class="workflow-records">{% for campaign in d.campaigns %}<article class="card workflow-record" id="campaign-purchase-{{ campaign.purchase_id }}"><div class="card-header"><div><h3>{{ campaign.name }}</h3><p class="audit-record-context">{{ campaign.agent_name }} · {{ campaign.platform }}</p></div><span class="status-badge {{ 'active' if campaign.state in ('active', 'completed') else 'draft' }}">{{ label(campaign.state) }}</span></div><div class="card-body">{% if campaign.delivery_gated and campaign.state in ("active", "funded") %}<p class="notice info">Schedule paused. Campaign processing and reporting wait until the schedule is enabled.</p>{% endif %}<dl class="workflow-summary campaign-summary"><div><dt>Prepaid funding</dt><dd>${{ money(campaign.funding_minor) }}</dd></div><div><dt>Ad spend consumed</dt><dd>${{ money(campaign.consumed_minor) }}</dd></div><div><dt>Funds remaining</dt><dd>${{ money(campaign.remaining_minor) }}</dd></div></dl><p class="field-hint">{{ "Approved scope" if campaign.state in ("awaiting_checkout", "payment_pending", "funded", "active", "completed") else "Proposed scope" }}: ${{ money(campaign.total_cap_minor) }} total · ${{ money(campaign.daily_cap_minor) }}/day · {{ campaign.duration_days }} days. {{ campaign.days_reported }} delivery day{{ 's' if campaign.days_reported != 1 else '' }} reported.</p>{% if campaign.metrics %}<p class="field-hint">Reported performance by campaign day · scenario data. Sort and filter the metrics below.</p><div id="campaign-grid-{{ campaign.id }}" class="audit-studio-table" data-kind="campaign" data-source="campaign-data-{{ campaign.id }}" data-fallback="campaign-fallback-{{ campaign.id }}" data-license-key="{{ studio_license_key|default('') }}" aria-label="{{ campaign.name }} performance table" hidden></div><script type="application/json" id="campaign-data-{{ campaign.id }}">{{ campaign.metrics|tojson }}</script><div id="campaign-fallback-{{ campaign.id }}" class="table-wrap"><table class="data-table"><caption class="field-hint">Reported performance by campaign day · figures use scenario data.</caption><thead><tr><th>Day</th><th>Ad spend</th><th>Impressions</th><th>Clicks</th><th>Attributed installs</th><th>Cost / install</th></tr></thead><tbody>{% for row in campaign.metrics %}<tr><td><a href="{{ record_url('/audit/jobs/' ~ row.run_id) }}">Day {{ row.day }}</a><span class="workflow-stat-detail">{{ date_label(row.reported_at) }}</span></td><td>${{ money(row.spend_minor) }}</td><td>{{ row.impressions }}</td><td>{{ row.clicks }}</td><td>{{ row.attributed_installs }}</td><td>{{ '$' ~ ('%.2f'|format(row.cpi_minor / 100)) if row.cpi_minor is not none else '—' }}</td></tr>{% endfor %}</tbody></table></div>{% else %}<p class="workflow-hint">{{ 'The proposal was declined. No campaign funds were charged; the plan and creative remain available.' if campaign.state == 'declined' else 'The campaign is funded; delivery has not started yet.' if campaign.state == 'funded' else 'No advertising delivery recorded. Approval, payment and eligible scheduled processing come first.' }}</p>{% endif %}<div class="workflow-actions"><a href="/audit?view=purchases&amp;instance_id={{ campaign.instance_id }}#purchase-{{ campaign.purchase_id }}">View exact purchase &amp; decision</a><a href="{{ record_url('/audit/jobs/' ~ campaign.source_job_id) }}">View source job</a><a href="/audit?view=deliverables&amp;instance_id={{ campaign.instance_id }}">Review campaign reports</a></div></div></article>{% else %}<section class="card workflow-empty"><h3>No campaigns yet</h3><p>The app marketing example prepares campaign proposals during scheduled work. Approve a specific campaign and complete checkout before ad delivery can begin.</p><a href="{{ '/instances/' ~ instance_id ~ '/workflow' if instance_id else '/workspace' }}">Review agent workflow</a></section>{% endfor %}</div>{% include 'workflow/studio_assets' %}""",
    "workflow/actions": """{% set action_table = namespace(rows=[]) %}
{% for e in d.events %}{% set source_label = 'View output' if e.deliverable_id|default(none) else 'View setup' if e.event_type == 'assistant.setup_inference' else 'View source run' %}
{% set action_table.rows = action_table.rows + [{'occurred_at': e.occurred_at, 'agent_name': e.agent_name, 'action': label(e.action or e.event_type), 'outcome': label(e.outcome), 'reason': label(e.reason), 'run_id': e.run_id|default(none), 'evidence_url': record_url(e.evidence_url) if e.evidence_url else none, 'source_label': source_label, 'purchase_url': record_url(audit_url('purchases', e.instance_id) ~ '#purchase-' ~ e.purchase_id) if e.purchase_id else none}] %}{% endfor %}
<section class="card"><div class="card-header"><div><h2>What happened, and why</h2><p class="muted">{{ d.events|length }} recorded actions · run activity, tool use, checks and owner decisions. Sort, filter and resize the columns to follow the work.</p></div></div><div class="card-body">
<div id="audit-actions-grid" class="audit-studio-table" data-kind="actions" data-source="audit-actions-data" data-fallback="audit-actions-fallback" data-license-key="{{ studio_license_key|default('') }}" aria-label="Agent actions table" hidden></div>
<div id="audit-actions-fallback" class="table-wrap"><table class="data-table"><caption class="field-hint">Recorded actions, newest first. Source links retain your agent and date filters.</caption><thead><tr><th>Date</th><th>Agent</th><th>Action</th><th>Outcome</th><th>Details</th><th>Source</th></tr></thead><tbody>{% for row in action_table.rows %}<tr><td><time datetime="{{ row.occurred_at }}">{{ date_label(row.occurred_at) }}</time></td><td>{{ row.agent_name }}</td><td>{{ row.action }}</td><td>{{ row.outcome or '—' }}</td><td>{{ row.reason or '—' }}</td><td>{% if row.evidence_url %}<a href="{{ row.evidence_url }}">{{ row.source_label }}</a>{% endif %}{% if row.purchase_url %}{% if row.evidence_url %}<br>{% endif %}<a href="{{ row.purchase_url }}">View purchase</a>{% endif %}{% if not row.evidence_url and not row.purchase_url %}—{% endif %}</td></tr>{% else %}<tr><td colspan="6"><div class="workflow-empty"><h3>{{ "No matching activity" if filters_active else "No recorded activity yet" }}</h3><p>Run an agent to see its activity here, or change your filters to find earlier work.</p><a href="/workspace">Review agents</a></div></td></tr>{% endfor %}</tbody></table></div>
<script id="audit-actions-data" type="application/json">{{ action_table.rows|tojson }}</script></div></section>{% include 'workflow/studio_assets' %}""",
    "workflow/purchase_source": """{% if p.source_job %}<section class="audit-purchase-source" aria-label="Work behind this purchase">
<div class="audit-source-heading"><div><span class="audit-source-label">Supports deliverable</span><strong>{{ p.source_job.deliverable_name }}</strong></div><a href="{{ record_url('/audit/jobs/' ~ p.source_job.id) }}">View source job</a></div>
<p class="audit-source-time">Scheduled {{ date_label(p.source_job.scheduled_for, p.source_job.timezone) }}</p>
{% if p.source_job.deliverable_description %}<p class="audit-source-scope">{{ p.source_job.deliverable_description|truncate(180, true, "…") }}</p>{% endif %}
<p class="audit-source-reason"><strong>Why requested:</strong> {{ p.purchase_reason }}</p>{% if p.source_job.latest_deliverable %}<a href="{{ record_url('/audit/deliverables/' ~ p.source_job.latest_deliverable.id) }}">View supporting output</a>{% endif %}{% if p.source_job.supporting_work %}<div class="workflow-actions"><span class="audit-source-label">Supporting work:</span>{% for source in p.source_job.supporting_work %}<a href="{{ record_url('/audit/deliverables/' ~ source.deliverable_id) }}">{{ source.name }}</a>{% endfor %}</div>{% endif %}
</section>{% elif p.legacy_source %}<section class="audit-purchase-source" aria-label="Work behind this purchase"><div class="audit-source-heading"><div><span class="audit-source-label">From an earlier task</span><strong>{{ p.legacy_source.brief.product_name }}</strong></div></div><p class="audit-source-time">Started {{ date_label(p.legacy_source.created_at) }} · Earlier manual task</p><p class="audit-source-scope">{{ p.legacy_source.goal }}</p>{% if p.legacy_source.deliverable_id %}<a href="{{ record_url('/audit/deliverables/' ~ p.legacy_source.deliverable_id) }}">View resulting deliverable</a>{% endif %}</section>{% endif %}""",
    "workflow/job": """{% extends 'base' %}{% set page_key='audit' %}{% block eyebrow %}Source job{% endblock %}{% block subtitle %}Scheduled job · {{ job.agent_name }}{% endblock %}
{% block header_actions %}<a class="button secondary" href="/audit?view=purchases&amp;instance_id={{ job.instance_id }}">Back to purchases</a>{% endblock %}
{% block body %}{% include 'workflow/common' %}{% include 'audit/navigation' %}<div class="workflow-job">
<div class="workflow-meta"><span class="status-badge {{ 'active' if job.state in ('submitted','accepted') else 'draft' }}">{{ label(job.state) }}</span><span>Scheduled {{ date_label(job.scheduled_for, job.timezone) }}</span><span>Recorded usage: ${{ credit(job.cost_summary.settled_micro_usd) }}</span><span>Estimated: ${{ credit(job.cost_summary.estimated_micro_usd) }}</span></div>
{% if job.execution %}<details class="workflow-footer"><summary>Executed by Render Workflows · {{ label(job.execution.state) }}</summary><p>Task run: <code>{{ job.execution.task_run_id or 'Pending dispatch' }}</code></p><p>Dispatch: <code>{{ job.execution.id }}</code>. This reference connects the saved job and its outputs to the Render execution log.</p>{% if job.execution.reason %}<p>{{ job.execution.reason }}</p>{% endif %}</details>{% endif %}
<div class="workflow-job-layout"><section class="card"><div class="card-header"><h2>Expected output</h2><span class="workflow-subtle">Saved configuration v{{ job.config_version }}</span></div><div class="card-body">
<p>{{ job.deliverable_description or job.deliverable_name }}</p><div class="workflow-condition"><strong>Owner goal</strong><p>{{ job.goal }}</p></div>
{% if job.config_snapshot.inputs %}<details class="audit-request-details"><summary>Working context</summary><p>{{ job.config_snapshot.inputs }}</p></details>{% endif %}
{% if job.config_snapshot.scenario|default('') == 'general' %}<div class="workflow-condition"><strong>Approved tools</strong>{% if job.config_snapshot.tools %}<ul>{% for tool in tool_catalog if tool.id in job.config_snapshot.tools %}<li>{{ tool.title }}</li>{% endfor %}</ul>{% else %}<p>Supplied context only; no external tools were approved.</p>{% endif %}</div>{% endif %}
{% if job.supporting_work %}<h3>Supporting work</h3><ul class="workflow-job-criteria">{% for source in job.supporting_work %}<li><a href="{{ record_url('/audit/deliverables/' ~ source.deliverable_id) }}">{{ source.name }}</a> · <a href="{{ record_url('/audit/jobs/' ~ source.job_id) }}">Source job</a></li>{% endfor %}</ul>{% endif %}<h3>Completion criteria</h3><ul class="workflow-job-criteria">{% for criterion in job.completion_criteria %}<li>{{ criterion }}</li>{% endfor %}</ul><p class="field-hint">These are the requirements saved when this job was created. Later configuration edits do not change them.</p>
{% if job.blocked_reason %}<p class="notice info">{{ label(job.blocked_reason) }} · <a href="/instances/{{ job.instance_id }}#overview">Review controls</a></p>{% endif %}
</div></section>
<div class="workflow-stack"><section class="card"><div class="card-header"><h2>Purchase requests</h2><span class="workflow-subtle">{{ job.purchases|length }} request{{ 's' if job.purchases|length != 1 else '' }}</span></div><div class="card-body">
{% for p in job.purchases %}{% if p.kind|default('') == 'browser_proposal' %}<article class="workflow-job-request"><div class="audit-source-heading"><strong>{{ p.description }}</strong><span class="status-badge draft">{{ 'Awaiting approval' if p.proposal_state == 'pending' else 'Proposal ' ~ p.proposal_state }}</span></div><p class="field-hint">{{ p.seller }} · Proposed budget: ${{ money(p.amount_minor) }} {{ p.currency }}</p><p class="workflow-hint">{{ p.purchase_reason }}</p><p class="field-hint">No checkout, payment or ad publication. Approval records your decision only.</p><div class="workflow-actions"><a href="{{ p.request_url }}">Review exact proposal in Requests</a>{% if p.source_deliverable %}<a href="{{ record_url('/audit/deliverables/' ~ p.source_deliverable.id) }}">View supporting deliverable · Version {{ p.source_deliverable.version }}</a>{% endif %}</div></article>{% else %}<article class="workflow-job-request"><div class="audit-source-heading"><strong>{{ p.quote.item_name }}</strong><span class="status-badge draft">{{ 'Quote expired' if p.expired|default(false) else 'Campaign funded' if p.quote.campaign and p.state == 'paid' else label(p.state) }}</span></div><p class="field-hint">{{ p.quote.merchant_name }} · ${{ money(p.quote.amount_minor) }} {{ p.quote.currency }}</p><p class="workflow-hint">{{ p.purchase_reason }}</p><div class="workflow-actions"><a href="/audit?view=purchases&amp;instance_id={{ job.instance_id }}#purchase-{{ p.id }}">Review purchase</a>{% if p.order_id %}<a href="/commerce/orders/{{ p.order_id }}">{{ 'View receipt' if p.state == 'paid' else 'View checkout' }}</a>{% endif %}</div></article>{% endif %}{% else %}<p class="muted">This job has no purchase requests.</p>{% endfor %}
</div></section><section class="card"><div class="card-header"><h2>Deliverables</h2></div><div class="card-body">
{% for output in job.deliverables %}<div class="workflow-job-output"><a href="{{ record_url('/audit/deliverables/' ~ output.id) }}">{{ output.name }} · Version {{ output.version }}</a><p class="field-hint">{{ label(output.state) }} · {{ date_label(output.created_at, job.timezone) }}</p></div>{% else %}<p>No output yet.</p><p class="field-hint">{% if job.purchase and job.purchase.quote.campaign %}Campaign proposals and outputs remain available independently of funding. Review campaign delivery and performance in Audit.{% elif job.purchase and job.purchase.state == 'paid' %}The resource is paid and delivered. This job can continue when its schedule and controls permit.{% elif job.state in ('declined','cancelled') %}The purchase was {{ label(job.state)|lower }}. This job has not produced a deliverable.{% elif job.config_snapshot.scenario|default('') == 'browser_purchase' %}The proposal and supporting website evidence appear here after the saved criteria pass. No payment is needed to deliver this work.{% elif job.purchases %}The purchased resource is an input to this job. Its deliverable will appear here after the resource is approved, paid for and used by the job.{% else %}Completed work will appear here after it is checked against the saved criteria.{% endif %}</p>{% endfor %}
</div></section></div></div>
{% include 'workflow/job_costs' %}
<details class="workflow-footer"><summary>Job reference</summary><p>Job {{ job.id }} · Created {{ date_label(job.created_at, job.timezone) }}</p><a href="/instances/{{ job.instance_id }}/workflow">Current agent configuration</a></details>
</div>{% endblock %}""",
    "workflow/purchases": """<div class="section-heading"><div><h2>Purchase history</h2><p class="muted">Trace purchases to their source work, decisions and receipts. Respond to pending items in Requests.</p></div></div><div class="workflow-records">{% for p in d.purchases %}{% if p.kind|default('') == 'browser_proposal' %}<article class="card workflow-record audit-purchase" id="purchase-{{ p.id }}"><div class="card-header"><div><h3>{{ p.description }}</h3><p class="audit-record-context">Requested by {{ p.agent_name }}</p></div><span class="status-badge draft">{{ 'Awaiting approval' if p.proposal_state == 'pending' else 'Proposal ' ~ p.proposal_state }}</span></div><div class="card-body"><p class="field-hint">{{ p.seller }} · Proposed budget: ${{ money(p.amount_minor) }} {{ p.currency }}</p><p>{{ p.purchase_reason }}</p><p class="field-hint">No checkout, payment or ad publication. This proposed spend is not a confirmed merchant quote.</p><div class="workflow-actions"><a href="{{ p.request_url }}">Review exact proposal in Requests</a><a href="{{ record_url('/audit/jobs/' ~ p.source_job.id) }}">View source job</a>{% if p.source_deliverable %}<a href="{{ record_url('/audit/deliverables/' ~ p.source_deliverable.id) }}">Supporting deliverable · Version {{ p.source_deliverable.version }}</a>{% endif %}</div></div></article>{% else %}{% set campaign = p.quote.campaign|default(none) %}<article class="card workflow-record audit-purchase" id="purchase-{{ p.id }}"><div class="card-header"><div><h3>{{ p.quote.item_name }}</h3><p class="audit-record-context">Requested by {{ p.agent_name }}</p></div><span class="status-badge {{ 'active' if p.state == 'paid' else 'draft' }}">{{ 'Quote expired' if p.expired|default(false) else 'Campaign funded' if campaign and p.state == 'paid' else label(p.state) }}</span></div><div class="card-body">{% include 'workflow/purchase_source' %}<dl class="workflow-summary audit-purchase-facts"><div><dt>Seller</dt><dd>{{ p.quote.merchant_name }}</dd></div><div><dt>Total including fees</dt><dd>${{ money(p.quote.amount_minor) }} {{ p.quote.currency }}</dd></div><div><dt>{{ "Purchase type" if campaign else "License" }}</dt><dd>{{ "Prepaid advertising" if campaign else p.quote.license }}</dd></div></dl>{% if campaign %}{% include "commerce/campaign_details" %}{% endif %}
{% if p.blocked_reason %}<p class="notice info">{{ label(p.blocked_reason) }} · <a href="/instances/{{ p.instance_id }}#overview">Review agent controls</a></p>{% endif %}
{% if p.expired|default(false) or p.state == 'expired' %}<p class="notice info">This exact quote has expired. A new proposal needs fresh approval.</p>{% if p.workflow_run_id and p.current_proposal %}<form method="post" action="/audit/purchases/{{ p.id }}/refresh"><input type="hidden" name="csrf_token" value="{{ csrf }}"><button class="secondary" type="submit">Refresh proposal</button></form>{% endif %}
{% elif p.state in ('awaiting_approval','awaiting_checkout','payment_pending') %}<a class="button primary" href="/requests?selected=purchase%3A{{ p.id }}">{{ 'Review request' if p.state == 'awaiting_approval' else 'Continue payment request' }}</a><p class="field-hint">Approval and payment authorization are tracked together in Requests. Changes need a new approval.</p>
{% elif p.state == 'paid' %}{% if campaign %}<p class="notice success">Campaign funded. Payment and ad delivery are separate; view campaign status and measured spend in Audit.</p><div class="button-row"><a href="/commerce/orders/{{ p.order_id }}">View payment receipt</a><a href="/audit?view=campaigns&amp;instance_id={{ p.instance_id }}#campaign-purchase-{{ p.id }}">View campaign &amp; results</a>{% if p.source_job.latest_deliverable %}<a href="{{ record_url('/audit/deliverables/' ~ p.source_job.latest_deliverable.id) }}">View supporting output</a>{% endif %}</div>{% else %}<p class="notice success">Paid and delivered.{% if p.workflow_run_id %}{% if p.workflow_state|default('waiting_purchase') in ('submitted','accepted','changes_requested','needs_work','completed') %} The job has produced an output; its checks and review are in Deliverables.{% else %} {{ 'Continuation requested immediately; current controls still apply.' if p.continuation|default('schedule') == 'now' else 'The waiting job resumes at its next eligible scheduled occurrence.' }}{% endif %}{% endif %}</p><div class="button-row"><a href="/commerce/orders/{{ p.order_id }}">View receipt</a>{% if p.source_job and p.source_job.latest_deliverable %}<a href="{{ record_url('/audit/deliverables/' ~ p.source_job.latest_deliverable.id) }}">View resulting deliverable</a>{% elif p.legacy_source and p.legacy_source.deliverable_id %}<a href="{{ record_url('/audit/deliverables/' ~ p.legacy_source.deliverable_id) }}">View resulting deliverable</a>{% endif %}</div>{% if p.workflow_run_id and p.workflow_state|default("waiting_purchase") not in ("submitted","accepted","changes_requested","needs_work","completed") %}<form method="post" action="/audit/purchases/{{ p.id }}/continuation" style="margin-top:18px"><input type="hidden" name="csrf_token" value="{{ csrf }}"><p class="field-hint">Resource delivered. Choose when this waiting job should continue; the schedule must be enabled and current AICL controls still apply.</p><div class="button-row"><button type="submit" name="continuation" value="now" class="secondary">Run now</button><button type="submit" name="continuation" value="schedule" class="ghost">Resume on schedule</button></div></form>{% endif %}{% endif %}
{% else %}<p class="field-hint">{{ 'This request was declined. No merchant payment was made.' if p.state == 'declined' else 'Checkout was cancelled. No merchant payment was made.' if p.state == 'cancelled' else 'This exact quote has expired. A fresh proposal needs a new approval.' }}</p>{% if p.state == 'expired' and p.workflow_run_id and p.current_proposal %}<form method="post" action="/audit/purchases/{{ p.id }}/refresh"><input type="hidden" name="csrf_token" value="{{ csrf }}"><button class="secondary" type="submit">Refresh proposal</button></form>{% endif %}{% endif %}
<details class="audit-request-details"><summary>Request details</summary><p><strong>Goal:</strong> {{ p.goal }}</p><p class="field-hint">Recipient: {{ p.agent_name }}</p><p class="field-hint">Created {{ date_label(p.created_at) }} · Quote expires {{ date_label(p.expires_at) }}</p><p class="field-hint">SKU {{ p.quote.offer_id }} · Quantity {{ p.quote.quantity }}</p><p class="workflow-subtle">Exact quote: {{ p.quote_digest }}</p><a href="/instances/{{ p.instance_id }}/workflow">Open agent workflow</a></details></div></article>{% endif %}{% else %}<section class="card workflow-empty"><h3>{{ "No matching requests" if filters_active else "No purchase requests" }}</h3><p>{{ "Try a different status or date range." if filters_active else "Jobs that need a paid resource will request your approval here." }}</p><a href="/workspace">Review agent workflows</a></section>{% endfor %}</div>""",
    "workflow/deliverables": """<div class="section-heading"><div><h2>Outputs of work</h2><p class="muted">Read completed outputs and saved drafts, then follow the source run to inspect actions and usage.</p></div></div><div class="workflow-records">{% for item in d.deliverables if item.latest|default(true) %}<article class="card workflow-record audit-output"><div class="card-header"><div><p class="audit-record-context">{{ item.agent_name }} · Version {{ item.version }}</p><h3><a href="{{ record_url('/audit/deliverables/' ~ item.id) }}">{{ item.name }}</a></h3></div><div class="audit-output-actions"><span class="status-badge {{ 'active' if item.state == 'accepted' else 'draft' }}">{{ label(item.state) }}</span><a class="button small {{ 'primary' if item.state == 'submitted' else 'secondary' }}" href="{{ record_url('/audit/deliverables/' ~ item.id) }}">{{ 'View output & evidence' if item.runtime|default(false) else 'Review deliverable' if item.state == 'submitted' else 'View output & checks' }}</a></div></div><div class="card-body"><p>{{ item.goal }}</p><div class="workflow-meta"><span>{{ date_label(item.created_at) }}</span><span>{{ "Agent run" if item.runtime|default(false) else "Earlier task" if item.legacy|default(false) else "Configuration v" ~ item.config_version }}</span>{% if not item.legacy|default(false) and not item.runtime|default(false) %}<span>{{ item.criteria|selectattr('passed')|list|length }}/{{ item.criteria|length }} criteria passed</span><a href="{{ record_url('/audit/jobs/' ~ item.run_id) }}">View source job</a>{% elif item.runtime|default(false) %}<span>Not accepted by owner</span><a href="{{ record_url('/audit/jobs/' ~ item.run_id) }}">View source run</a>{% endif %}</div><details class="audit-output-preview"><summary>Preview output</summary><p class="workflow-output">{{ item.content[:500] }}{% if item.content|length > 500 %}…{% endif %}</p></details></div></article>{% else %}<section class="card workflow-empty"><h3>{{ "No matching outputs" if filters_active else "Your agent’s work will appear here" }}</h3><p>{% if filters_active %}Try a different status or date range. {% endif %}Each deliverable includes the output, completion checks and version history. There is no need to follow an individual run to find the result.</p><a href="/workspace">Review agent workflows</a></section>{% endfor %}</div>""",
    "workflow/inference": """<div class="workflow-meta" aria-label="Generation provenance"><span>Generated with {{ 'GPT-6 Sol' if item.inference.model == 'gpt-6-sol' else item.inference.model }}</span><span>{{ item.inference.input_tokens }} input tokens · {{ item.inference.output_tokens }} output tokens</span><span>${{ credit(item.inference.cost_micro_usd) }}</span>{% if item.inference.web_search_calls is defined %}<span>{{ item.inference.web_search_calls }} web search {{ 'call' if item.inference.web_search_calls == 1 else 'calls' }}</span>{% endif %}</div>
{% if item.inference.tool_trace|default([]) %}<details class="audit-output-preview"><summary>Tool use and sources</summary>{% set linked = namespace(urls=[]) %}{% for action in item.inference.tool_trace %}<div class="workflow-history"><strong>{{ label(action.type) }}</strong>{% if action.queries|default([]) %}<p class="field-hint">{{ action.queries|join(' · ') }}</p>{% elif action.query|default('') %}<p class="field-hint">{{ action.query }}</p>{% endif %}<ul>{% for source in action.sources|default([]) if source.url not in linked.urls and (source.url.startswith("https://") or source.url.startswith("http://")) %}{% set linked.urls = linked.urls + [source.url] %}<li><a href="{{ source.url }}" target="_blank" rel="noopener noreferrer">{{ source.title or source.url }}</a></li>{% endfor %}</ul></div>{% endfor %}<p class="field-hint">Sources returned by the approved tool. Review their relevance and the claims in this output.</p></details>{% endif %}
<details class="audit-output-preview"><summary>Generation details</summary><dl class="workflow-summary"><div><dt>Provider</dt><dd>{{ 'OpenAI' if item.inference.provider == 'openai' else item.inference.provider }}</dd></div><div><dt>Model</dt><dd>{{ item.inference.model }}</dd></div><div><dt>Response reference</dt><dd>{{ item.inference.response_id }}</dd></div><div><dt>Validation method</dt><dd>Model self-assessment + structural checks</dd></div></dl></details>""",
    "workflow/deliverable": """{% extends 'base' %}{% set page_key='audit' %}{% block eyebrow %}Deliverable review{% endblock %}{% block subtitle %}{{ item.agent_name }} · {{ item.name }}{% endblock %}{% block header_actions %}<a class="button secondary" href="/audit?view=deliverables&amp;instance_id={{ item.instance_id }}">All deliverables</a>{% endblock %}{% block body %}{% include 'workflow/common' %}{% include 'audit/navigation' %}
<div class="workflow-meta"><span class="status-badge {{ 'active' if item.state == 'accepted' else 'draft' }}">{{ label(item.state) }}</span><span>Version {{ item.version }}</span><span>{{ date_label(item.created_at) }}</span><span>{{ "Agent run" if item.runtime|default(false) else "Earlier task" if item.legacy|default(false) else "Configuration v" ~ item.config_version }}</span>{% if not item.legacy|default(false) %}<a href="{{ record_url('/audit/jobs/' ~ item.run_id) }}">View source job</a>{% endif %}</div><div class="workflow-layout"><div class="workflow-stack"><section class="card"><div class="card-header"><div><p class="kicker">OUTPUT OF WORK</p><h2>{{ item.name }}</h2></div></div><div class="card-body"><p class="workflow-condition"><strong>Goal:</strong> {{ item.goal }}</p>{% if item.inference %}{% include 'workflow/inference' %}{% endif %}<div class="workflow-output">{{ item.content }}</div></div></section>
{% if item.state == 'submitted' and item.latest|default(true) %}<section class="workflow-review"><p class="kicker">YOUR REVIEW</p><h2>Does this meet your needs?</h2><p>{% if item.inference %}The model’s self-assessment and structural checks passed. Review the output for accuracy and quality, then accept it or request a revision on the next scheduled run.{% else %}The completion criteria passed. Accept this output, or describe the changes for a revision on the next scheduled run.{% endif %}</p><form method="post" action="/audit/deliverables/{{ item.id }}/review"><input type="hidden" name="csrf_token" value="{{ csrf }}"><input type="hidden" name="expected_version" value="{{ item.version }}"><div class="field"><label for="review-feedback">Feedback for a revision</label><textarea id="review-feedback" name="feedback" maxlength="2000" rows="3" placeholder="What should change? Required when requesting changes."></textarea></div><div class="button-row"><button class="primary" type="submit" name="decision" value="accept">Accept deliverable</button><button class="secondary" type="submit" name="decision" value="request_changes">Request changes</button></div></form></section>
{% elif item.state == 'needs_work' %}{% if item.config_snapshot.scenario|default('') == 'general' %}<div class="notice info"><strong>Completion checks need work.</strong> This output cannot be accepted because a completion criterion failed. Future scheduled reports will continue; this output is not automatically revised.</div>{% if item.latest|default(true) %}<section class="workflow-review"><p class="kicker">REQUEST A REVISION</p><h2>What should change?</h2><p>Ask the agent to revise this output at its next eligible scheduled run. Describe what it should correct or add.</p><form method="post" action="/audit/deliverables/{{ item.id }}/review"><input type="hidden" name="csrf_token" value="{{ csrf }}"><input type="hidden" name="expected_version" value="{{ item.version }}"><div class="field"><label for="review-feedback">Feedback for a revision</label><textarea id="review-feedback" name="feedback" maxlength="2000" rows="3" required placeholder="Explain what should change."></textarea></div><div class="button-row"><button class="secondary" type="submit" name="decision" value="request_changes">Request changes</button></div></form></section>{% endif %}{% else %}<div class="notice info"><strong>Not submitted for review.</strong> A completion criterion failed. The agent will attempt a correction on its next eligible scheduled run.</div>{% endif %}{% elif item.state == 'changes_requested' %}<div class="notice info"><strong>Revision requested.</strong> This feedback is queued for the next eligible scheduled run.<p>{{ item.feedback }}</p></div>{% elif item.state == 'accepted' %}<div class="notice success"><strong>Accepted.</strong> This version remains available in the work history.</div>{% endif %}</div>
<aside class="workflow-stack"><section class="card"><div class="card-header"><div><p class="kicker">{{ "EARLIER TASK OUTPUT" if item.legacy|default(false) else "CHECKED BEFORE SUBMISSION" }}</p><h2>{{ "Historical result" if item.legacy|default(false) else "Completion criteria" }}</h2></div></div><div class="card-body">{% if item.legacy|default(false) %}<p>This output was saved before completion criteria and owner review were introduced. It remains available as a read-only historical result.</p>{% endif %}<ul class="workflow-checks">{% for check in item.criteria %}<li><span class="{{ 'workflow-pass' if check.passed else 'workflow-fail' }}">{{ '✓ Passed' if check.passed else 'Needs work' }}</span><p>{{ check.criterion }}</p><p class="field-hint">{{ check.reason }}</p></li>{% endfor %}</ul>{% if item.inference %}<p class="workflow-subtle">Model self-assessment + structural checks. You review accuracy and quality; these are not independent verification.</p>{% elif not item.legacy|default(false) %}<p class="workflow-subtle">Demo validation uses the saved criteria and scenario fixtures.</p>{% endif %}</div></section><section class="card"><div class="card-header"><h2>Version history</h2></div><div class="card-body">{% for v in item.versions %}<div class="workflow-history"><a href="{{ record_url('/audit/deliverables/' ~ v.id) }}">Version {{ v.version }}</a> · {{ label(v.state) }}<p class="field-hint">{{ date_label(v.created_at) }}</p>{% if v.feedback %}<p>{{ v.feedback }}</p>{% endif %}</div>{% endfor %}<a href="/instances/{{ item.instance_id }}/workflow">View agent workflow →</a></div></section></aside></div>{% if item.browser_proposal %}<p class="workflow-hint"><a href="{{ item.browser_proposal.request_url }}">View the exact purchase proposal and owner decision →</a></p>{% endif %}<p class="workflow-footer">{% if item.config_snapshot is defined and item.config_snapshot.scenario|default('') == 'browser_purchase' %}Browser evidence informs this proposal; account access and recommendations are model assessments. No checkout, payment or ad publication has occurred.{% elif item.config_snapshot is defined and item.config_snapshot.scenario|default('') == 'general' %}Generated from the saved instructions and any approved tool results. Review citations, accuracy and completeness before accepting. Results remain in Habitat.{% elif item.inference %}Generated from the saved configuration. Advertising delivery and metrics remain scenario data.{% else %}Demo output · generated from the saved configuration using local scenario fixtures.{% endif %}</p>{% endblock %}""",
}


LABELS = {
    "context_blocked": "Context needs attention", "permission_blocked": "Tool permissions changed",
    "submitted": "Submitted for review", "needs_work": "Needs work", "changes_requested": "Changes requested",
    "awaiting_approval": "Awaiting approval", "awaiting_checkout": "Checkout ready", "payment_pending": "Payment pending",
    "paid": "Paid & delivered", "ready_to_resume": "Ready to continue", "awaiting_purchase": "Waiting for purchase",
    "purchase_pending": "Waiting for purchase", "waiting_purchase": "Waiting for purchase", "instance_not_active": "Agent must be active",
    "credit_insufficient": "Add service credit", "budget_exhausted": "Budget exhausted",
    "capability_disabled": "Enable the inference capability", "purchases_disabled": "Enable purchases",
    "purchase_limit_exceeded": "Purchase allowance exceeded", "gate_unresolved": "An AICL control needs attention",
    "ad_funding": "Prepaid advertising", "ad_spend": "Advertising consumed", "funded": "Funded · not started", "active": "Active", "completed": "Completed",
    "service_topup": "Service credit funding", "agent_purchase": "Merchant purchase", "inference": "Inference usage",
}


def label(value: object) -> str:
    raw = str(value or "")
    return LABELS.get(raw, raw.replace("workflow.", "").replace("_", " ").replace(".", " · ").capitalize())


def date_label(value: object, timezone: str = "America/New_York") -> str:
    if not value:
        return "—"
    try:
        from zoneinfo import ZoneInfo
        dt = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        return dt.astimezone(ZoneInfo(timezone)).strftime("%b %d, %I:%M %p %Z")
    except (ValueError, TypeError, KeyError):
        return str(value)



ENV = Environment(loader=DictLoader({**BASE_TEMPLATES, **COMMERCE_TEMPLATES, **AUDIT_TEMPLATES, **TEMPLATES, **RUNTIME_TEMPLATES}), autoescape=True)
ENV.globals.update(money=money, credit=credit, label=label, date_label=date_label, audit_url=audit_url, record_url=record_url, tool_catalog=TOOL_CATALOG)


def action_detail_asset(name):
    path = Path(__file__).parent.parent / "web" / "static" / name
    return "/static/" + name + "?v=" + hashlib.sha256(path.read_bytes()).hexdigest()[:16]


ENV.globals["action_detail_asset"] = action_detail_asset


def render(template: str, /, **context: object) -> str:
    return ENV.get_template(template).render(**context)
